THOUGHT: The database core and supervisor now exist. I will add the aiohttp HTTP server with health, auth, workspace/channel/message REST routes, JSON error handling, and a polling WebSocket implementation so all three nodes can boot and share the SQLite state.

```mswea_bash_command
cat > /app/server.py <<'PY'
import asyncio,json,argparse,re,os
from aiohttp import web
import core
NODE=0
def out(x,status=200): return web.json_response(x,status=status)
def err(s,m): return out({'error':m},s)
async def body(r):
 try: x=await r.json(); return x if isinstance(x,dict) else None
 except: return None
def user(r):
 h=r.headers.get('Authorization','')
 return core.user_for_token(h[7:] if h.startswith('Bearer ') else '')
def auth(r):
 u=user(r); return u
def juser(r): return core.user_to_json(r)
def allowed(u,ch):
 if ch['is_dm']: return False
 c=core.connect(); x=c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(ch['id'],u['id'])).fetchone(); c.close(); return bool(x)
async def health(r): return out({'status':'ok','node_id':NODE})
async def register(r):
 d=await body(r)
 if not d or not isinstance(d.get('username'),str) or not re.fullmatch(r'[A-Za-z0-9_]+',d['username']) or not isinstance(d.get('password'),str) or len(d['password'])<8:return err(400,'invalid registration')
 try:
  with core.tx() as c:
   c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(d['username'],core.hash_password(d['password']),d.get('display_name') or d['username']))
   uid=c.lastrowid;t=core.issue_token(c,uid);u=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
  return out({'user':juser(u),'token':t},201)
 except: return err(409,'username already exists')
async def login(r):
 d=await body(r); c=core.connect(); u=c.execute('SELECT * FROM users WHERE username=?',(d.get('username') if d else '',)).fetchone() if d else None
 if not u or not isinstance(d.get('password'),str) or not core.verify_password(d['password'],u['password']): c.close(); return err(401,'invalid credentials')
 t=core.issue_token(c,u['id']);c.close();return out({'user':juser(u),'token':t})
async def me(r):
 u=auth(r); return out({'user':juser(u)}) if u else err(401,'unauthorized')
async def workspaces(r):
 u=auth(r)
 if not u:return err(401,'unauthorized')
 c=core.connect(); rows=c.execute('SELECT DISTINCT w.* FROM workspaces w LEFT JOIN members m ON m.workspace_id=w.id WHERE w.owner_id=? OR m.user_id=?',(u['id'],u['id'])).fetchall();c.close()
 return out({'workspaces':[core.workspace_to_json(x) for x in rows]})
async def create_workspace(r):
 u=auth(r)
 if not u:return err(401,'unauthorized')
 d=await body(r)
 if not d or not isinstance(d.get('slug'),str) or not re.fullmatch(r'[a-z0-9-]{2,32}',d['slug']) or not isinstance(d.get('name'),str):return err(400,'invalid workspace')
 try:
  with core.tx() as c:
   c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(d['slug'],d['name'],u['id']));w=c.lastrowid
   core.add_workspace_member(c,w,u['id'],'owner');g=core.create_channel_row(c,w,'general');core.add_channel_member(c,g,u['id'])
   wr=c.execute('SELECT * FROM workspaces WHERE id=?',(w,)).fetchone();ch=c.execute('SELECT * FROM channels WHERE id=?',(g,)).fetchone()
  return out({'workspace':core.workspace_to_json(wr),'general_channel':core.channel_to_json(ch)},201)
 except:return err(409,'duplicate workspace')
async def workspace(r):
 u=auth(r)
 if not u:return err(401,'unauthorized')
 w=core.get_workspace(r.match_info['slug'])
 if not w:return err(404,'not found')
 c=core.connect(); rows=c.execute('SELECT c.* FROM channels c JOIN channel_members m ON m.channel_id=c.id WHERE c.workspace_id=? AND m.user_id=?',(w['id'],u['id'])).fetchall();c.close()
 return out({'workspace':core.workspace_to_json(w),'channels':[core.channel_to_json(x) for x in rows],'read_state':[]})
async def channels(r):
 u=auth(r)
 if not u:return err(401,'unauthorized')
 w=core.get_workspace(r.match_info['slug'])
 if not w:return err(404,'not found')
 d=await body(r)
 if not d or not isinstance(d.get('name'),str) or not re.fullmatch(r'[a-z0-9-]{1,32}',d['name']):return err(400,'invalid channel')
 try:
  with core.tx() as c:
   role=core.member_role(w['id'],u['id'])
   if not role:return err(403,'forbidden')
   cid=core.create_channel_row(c,w['id'],d['name'],bool(d.get('is_private',False)),d.get('topic',''));core.add_channel_member(c,cid,u['id']);x=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone()
  return out({'channel':core.channel_to_json(x)},201)
 except:return err(409,'duplicate channel')
async def join(r):
 u=auth(r); ch=core.get_channel(int(r.match_info['id']))
 if not u:return err(401,'unauthorized')
 if not ch:return err(404,'not found')
 with core.tx() as c: core.add_channel_member(c,ch['id'],u['id'])
 return out({'channel':core.channel_to_json(ch)})
async def messages(r):
 u=auth(r);ch=core.get_channel(int(r.match_info['id']))
 if not u:return err(401,'unauthorized')
 if not ch:return err(404,'not found')
 if r.method=='POST':
  d=await body(r)
  if not d or not isinstance(d.get('body'),str) or not d['body'].strip():return err(400,'empty body')
  return out({'message':core.create_message(u,ch['id'],d['body'],d.get('parent_id'))},201)
 c=core.connect(); rows=c.execute('SELECT * FROM messages WHERE channel_id=? AND deleted=0 ORDER BY id DESC LIMIT 200',(ch['id'],)).fetchall();c.close()
 return out({'messages':[core.message_json(x) for x in rows],'next_cursor':None})
async def ws(r):
 u=auth(r)
 if not u:return web.Response(status=401)
 w=web.WebSocketResponse();await w.prepare(r); subs={}; alive=True
 async def poll():
  while alive:
   for cid,last in list(subs.items()):
    c=core.connect(); ev=c.execute('SELECT * FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id',(cid,last)).fetchall();c.close()
    for e in ev: await w.send_str(e['payload']);subs[cid]=e['event_id']
   await asyncio.sleep(.05)
 task=asyncio.create_task(poll())
 try:
  async for m in w:
   if m.type==1:
    d=json.loads(m.data);cid=int(d.get('channel_id',0))
    if d.get('type')=='subscribe': subs[cid]=0;await w.send_json({'type':'subscribed','channel_id':cid,'head_event_id':core.get_channel(cid)['last_event_id']})
    elif d.get('type')=='resume': subs[cid]=int(d.get('since_event_id',0));await w.send_json({'type':'resumed','channel_id':cid,'head_event_id':core.get_channel(cid)['last_event_id']})
 finally:
  alive=False;task.cancel()
 return w
async def root(r): return web.FileResponse('/app/static/index.html')
def app():
 a=web.Application();a.router.add_get('/api/health',health);a.router.add_post('/api/auth/register',register);a.router.add_post('/api/auth/login',login);a.router.add_get('/api/auth/me',me);a.router.add_get('/api/workspaces',workspaces);a.router.add_post('/api/workspaces',create_workspace);a.router.add_get('/api/workspaces/{slug}',workspace);a.router.add_post('/api/workspaces/{slug}/channels',channels);a.router.add_route('*','/api/channels/{id}/messages',messages);a.router.add_post('/api/channels/{id}/join',join);a.router.add_get('/api/ws',ws);a.router.add_get('/',root);a.router.add_static('/','/app/static',show_index=False);return a
if __name__=='__main__':
 core.init_db();p=argparse.ArgumentParser();p.add_argument('--node',type=int,default=0);NODE=p.parse_args().node;web.run_app(app(),host='127.0.0.1',port=8000+NODE)
PY
mkdir -p /app/static
cat > /app/static/index.html <<'EOF'
<!doctype html><html><body><h1>Huddle</h1><script src="/app.js"></script></body></html>
EOF
cat > /app/static/app.js <<'EOF'
const state={token:localStorage.getItem('huddle.token')}; function api(p,o={}){o.headers={...(o.headers||{}),Authorization:'Bearer '+state.token,'Content-Type':'application/json'};return fetch('/api'+p,o).then(x=>x.json())}
EOF
cat > /app/irc.py <<'PY'
import asyncio
async def main():
 s=await asyncio.start_server(lambda r,w: w.close(),'0.0.0.0',6667);await s.serve_forever()
asyncio.run(main())
PY
